const lib = global.get('ems_lib'); const st = lib.states();
const val = s => { const v = parseFloat(s); return Number.isFinite(v) ? v : lib.num(st, String(s), 0); };
const grens = val(env.get('GRENS')), marge = val(env.get('MARGE')), richting = env.get('RICHTING') || 'boven';
const vorige = context.get('aan') || false;
const waarde = parseFloat(msg.payload);
if (!Number.isFinite(waarde)) { node.status({ fill: 'red', shape: 'ring', text: 'geen getal' }); return null; }
const aan = lib.latch(waarde, grens, marge, richting, vorige);
context.set('aan', aan);
msg.latch = { vorige, grens, marge, richting, waarde };
msg.payload = aan;
node.status({ fill: aan ? 'green' : 'grey', shape: 'dot', text: `${waarde} ${richting} ${grens}±${marge} → ${aan}` });
return msg;

const min_ms = (Number(env.get('MIN_MINUTEN')) || 5) * 60e3;
const now = Date.now();
const laatste = context.get('laatste');   // { waarde, t }
const nieuw = msg.payload;
if (laatste && laatste.waarde === nieuw) { node.status({ fill: 'grey', shape: 'dot', text: `ongewijzigd (${nieuw})` }); return [msg, null]; }
if (!msg.force && laatste && now - laatste.t < min_ms) {
  msg.wacht_s = Math.ceil((min_ms - (now - laatste.t)) / 1000);
  node.status({ fill: 'yellow', shape: 'ring', text: `wacht ${msg.wacht_s}s (${laatste.waarde}→${nieuw})` });
  return [null, msg];
}
context.set('laatste', { waarde: nieuw, t: now });
node.status({ fill: 'green', shape: 'dot', text: `→ ${nieuw}` });
return [msg, null];

const lib = global.get('ems_lib'); const st = lib.states();
// ---- BRON-ENTITEITEN (één plek om te wisselen na de meterfix / P1) ----
const SRC = {
  omvormer_ac:   'sensor.omvormer_werkelijk_vermogen',      // Huawei, W (+ = levert)
  net_vermogen:  'sensor.elektriciteitsmeter_vermogen',      // Huawei/DTSU, W (+ = afname, − = injectie)  → later P1
  pv_vandaag:    ['sensor.energy_production_today_3', 'sensor.energy_production_today_4'],
  pv_rest:       ['sensor.energy_production_today_remaining_3', 'sensor.energy_production_today_remaining_4'],
};
const omv = lib.num(st, SRC.omvormer_ac, 0);
const net = lib.num(st, SRC.net_vermogen, 0);
const som = ids => ids.reduce((a, id) => a + lib.num(st, id, 0), 0);
const b = {
  huisverbruik: Math.round(omv + net),
  netafname:    Math.round(Math.max(net, 0)),
  zonneoverschot: Math.round(Math.max(-net, 0)),
  zonvoorspelling_vandaag: Math.round(som(SRC.pv_vandaag) * 10) / 10,
  zonvoorspelling_rest:    Math.round(som(SRC.pv_rest) * 10) / 10,
};
flow.set('bronnen', b);           // voor de planner-tab (via global hieronder)
global.set('ems_bronnen', b);
msg.bron = b;
return msg;

const lib = global.get('ems_lib'); const st = lib.states();
const PRIJS_SENSOR = 'sensor.engie_engie_flow_flanders_huidige_prijs';   // ← stap C: dynamisch device
const slots = lib.prijsSlots(st, PRIJS_SENSOR);
global.set('ems_prijs', { sensor: PRIJS_SENSOR, slots: slots.map(s => ({ start: s.start.toISOString(), end: s.end.toISOString(), prijs: s.prijs })) });
const nu = new Date(); const cur = slots.find(s => nu >= s.start && nu < s.end);
const vandaag = slots.filter(s => s.start.toDateString() === nu.toDateString()).map(s => s.prijs);
msg.payload = cur ? cur.prijs : null;
msg.prijs = { n_slots: slots.length, min_vandaag: Math.min(...vandaag), max_vandaag: Math.max(...vandaag),
              gem_vandaag: vandaag.length ? vandaag.reduce((a, b) => a + b, 0) / vandaag.length : null };
return msg;

const lib = global.get('ems_lib'); const st = lib.states();
const nu = new Date();
const e = {
  nu, tick: msg.topic,
  soc: lib.num(st, 'sensor.batterijen_batterijpercentage', 100),
  vloer: lib.num(st, 'input_number.batterij_vloer', 40),
  herstel_doel: lib.num(st, 'input_number.batterij_herstel_doel', 70),
  meepomp_grens: lib.num(st, 'input_number.batterij_meepomp_grens', 70),
  netladen_doel: lib.num(st, 'input_number.ems_netladen_doel', 90),
  laaduren: Math.round(lib.num(st, 'input_number.ems_laaduren', 4)),
  marge: lib.num(st, 'input_number.ems_hysterese_marge', 5),
  zonnedag_drempel: lib.num(st, 'input_number.goede_zonnedag_drempel', 18),
  deadline: lib.todayAt(lib.str(st, 'input_datetime.herstel_deadline', '15:00:00'), nu),
  avond: lib.todayAt(lib.str(st, 'input_datetime.avond_reserve_tijd', '19:00:00'), nu),
  t_prijssturing: lib.on(st, 'input_boolean.ems_prijssturing'),
  t_herstelregel: lib.on(st, 'input_boolean.ems_herstelregel'),
  t_herstel_ook_zon: lib.on(st, 'input_boolean.ems_herstel_ook_op_zonnedag'),
  ev_modus: lib.str(st, 'input_select.ems_ev_laadmodus', 'Uit'),
  ev_max_a: lib.num(st, 'input_number.ems_ev_max_stroom', 16),
  assist_w: lib.num(st, 'input_number.ems_batterij_assist_vermogen', 2000),
  batterij_modus: lib.str(st, 'input_select.batterij_modus', 'Auto'),
  planner_bron: lib.str(st, 'input_select.ems_planner_bron', 'Regels'),
};
const bron = global.get('ems_bronnen') || {};
e.zonneoverschot = bron.zonneoverschot ?? 0;
e.zonvoorspelling_vandaag = bron.zonvoorspelling_vandaag ?? 0;
const pr = global.get('ems_prijs') || { slots: [] };
e.slots = pr.slots.map(s => ({ start: new Date(s.start), end: new Date(s.end), prijs: s.prijs }));
// afgeleide basisbooleans (port van 13/08-templates)
e.boven_vloer = e.soc > e.vloer;
e.goede_zonnedag = e.zonvoorspelling_vandaag >= e.zonnedag_drempel;
msg.ems = e; msg.prev = flow.get('planner_prev') || {};
return msg;

const lib = global.get('ems_lib'); const e = msg.ems;
const van = new Date(e.nu); van.setHours(0, 0, 0, 0);
const tot = new Date(van); tot.setDate(tot.getDate() + 1);
const g = lib.goedkoopsteUren(e.slots, e.laaduren, van, tot, e.nu);
e.goedkoopste_uren = g.is_now; e.blokken = g.blokken;
return msg;

const lib = global.get('ems_lib'); const e = msg.ems; const prev = msg.prev;
// uren nodig: tekort × 15 kWh ÷ 5 kW, cap 6
const tekort = Math.max(e.herstel_doel - e.soc, 0);
e.herstel_uren = Math.min(Math.ceil(tekort / 100 * 15 / 5), 6);
const voor_deadline = e.nu < e.deadline;
const zonnedag_ok = !e.goede_zonnedag || e.t_herstel_ook_zon;
// hysterese (2b): nodig onder doel − marge, blijft nodig tot doel bereikt
const soc_ok = lib.latch(e.soc, e.herstel_doel, e.marge, 'onder', !!prev.herstel_nodig);
e.herstel_nodig = soc_ok && voor_deadline && zonnedag_ok;
// laadvenster: goedkoopste resterende uren vóór de deadline (look_ahead + end)
if (e.herstel_nodig) {
  const g = lib.goedkoopsteUren(e.slots, Math.max(e.herstel_uren, 1), e.nu, e.deadline, e.nu);
  // look_ahead: het lopende slot telt mee als het nog niet voorbij is
  const lopend = e.slots.find(s => e.nu >= s.start && e.nu < s.end);
  const g2 = lopend ? lib.goedkoopsteUren(e.slots, Math.max(e.herstel_uren, 1), lopend.start, e.deadline, e.nu) : g;
  e.herstel_venster = g2.is_now; e.herstel_blokken = g2.blokken;
} else { e.herstel_venster = false; e.herstel_blokken = []; }
return msg;

const lib = global.get('ems_lib'); const e = msg.ems; const prev = msg.prev;
const soc_ok = lib.latch(e.soc, e.netladen_doel, e.marge, 'onder', !!prev.netladen_gewenst);
const prijs = e.t_prijssturing && e.goedkoopste_uren && soc_ok;
const herstel = e.t_herstelregel && e.herstel_nodig && e.herstel_venster;
e.netladen_gewenst = prijs || herstel;
e.netladen_reden = prijs && herstel ? 'prijssturing + herstel' : prijs ? 'prijssturing' : herstel ? 'herstel' : 'geen';
return msg;

const lib = global.get('ems_lib'); const e = msg.ems; const prev = msg.prev;
e.fase = e.nu < e.deadline ? 1 : e.nu < e.avond ? 2 : 3;
e.fase_tekst = { 1: '1 — herstel-fase (geen batterij→EV)', 2: '2 — dag-fase (batterij→EV boven meepomp-grens)', 3: '3 — avond-fase (geen batterij→EV)' }[e.fase];
const soc_ok = lib.latch(e.soc, e.meepomp_grens, e.marge, 'boven', !!prev.assist_toegestaan);
e.assist_toegestaan = e.boven_vloer && e.fase === 2 && soc_ok;
return msg;

const e = msg.ems;
const SPANNING = 230;               // 1-fase-aansluiting bevestigd 10/09 (Alfen 1F, max ~7 kW)
const assist = e.assist_toegestaan ? e.assist_w : 0;
let a = 0;
if (e.ev_modus === 'Volle kracht') a = Math.round(e.ev_max_a);
else if (e.ev_modus === 'Zon-overschot') { const x = e.zonneoverschot / SPANNING; a = x < 6 ? 0 : Math.round(Math.min(x, e.ev_max_a)); }
else if (e.ev_modus === 'Zon + batterij') { const x = (e.zonneoverschot + assist) / SPANNING; a = x < 6 ? 0 : Math.round(Math.min(x, e.ev_max_a)); }
e.ev_doelstroom = a;
return msg;

const e = msg.ems;
// Batterijvermogen: + laden (net toegestaan) / − ontladen (assist naar EV) / 0 = auto (zelfconsumptie)
let batt_w = 0, modus = 'auto', reden = 'zelfconsumptie';
if (e.netladen_gewenst)        { batt_w = 5000;  modus = 'laden';    reden = 'netladen: ' + e.netladen_reden; }
else if (e.assist_toegestaan && e.ev_modus === 'Zon + batterij' && e.ev_doelstroom > 0)
                               { batt_w = -e.assist_w; modus = 'ontladen'; reden = 'batterij→EV, ' + e.fase_tekst; }
else                           { reden = 'auto — ' + e.fase_tekst; }
// horizon: gekozen laadblokken + herstelblokken als slots
const horizon = [...(e.blokken || []).map(b => ({ start: b.start, end: b.end, batt_W: 5000, ev_A: 0, prijs: b.gem, bron: 'prijssturing' })),
                 ...(e.herstel_blokken || []).map(b => ({ start: b.start, end: b.end, batt_W: 5000, ev_A: 0, prijs: b.gem, bron: 'herstel' }))]
                .sort((x, y) => new Date(x.start) - new Date(y.start));
// verwachte kost van het plan (alleen netladen-slots, 5 kW × uren × prijs) — K9-basis
const kost = horizon.reduce((s, h) => s + 5 * ((new Date(h.end) - new Date(h.start)) / 3600e3) * (h.prijs || 0), 0);
msg.plan = {
  batterij_vermogen: batt_w, modus, reden, horizon, kost_verwacht: Math.round(kost * 100) / 100,
  ev_stroom: e.ev_doelstroom, bron: 'regels',
  // pariteit / debug
  netladen_gewenst: e.netladen_gewenst, netladen_reden: e.netladen_reden,
  assist_toegestaan: e.assist_toegestaan, fase_tekst: e.fase_tekst,
  herstel_nodig: e.herstel_nodig, herstel_uren: e.herstel_uren, herstel_venster: e.herstel_venster,
  goedkoopste_uren: e.goedkoopste_uren, blokken: e.blokken, soc: e.soc,
};
flow.set('planner_prev', { herstel_nodig: e.herstel_nodig, netladen_gewenst: e.netladen_gewenst, assist_toegestaan: e.assist_toegestaan });
global.set('ems_plan_regels', msg.plan);
return msg;

const bron = msg.ems.planner_bron;
if (bron === 'EMHASS') { node.status({ fill: 'grey', shape: 'ring', text: 'EMHASS vult contract' }); return [null, msg]; }
node.status({ fill: 'green', shape: 'dot', text: `regels → contract (${msg.plan.modus}, EV ${msg.plan.ev_stroom} A)` });
return [msg, msg];

// ==== EMS-bibliotheek (geladen in global.ems_lib) ====
const lib = {};
lib.states = function () {
  const g = global.get('homeassistant') || {};
  const srv = g.homeAssistant || Object.values(g)[0];
  if (!srv || !srv.states) throw new Error('HA global context store niet beschikbaar — zet "Enable global context store" aan op de server-node');
  return srv.states;
};
lib.num = function (st, id, dflt) {
  const e = st[id]; if (!e) return dflt;
  const v = parseFloat(e.state); return Number.isFinite(v) ? v : dflt;
};
lib.str = function (st, id, dflt) { const e = st[id]; return e ? e.state : dflt; };
lib.on  = function (st, id) { const e = st[id]; return !!e && e.state === 'on'; };
lib.attr = function (st, id, a, dflt) { const e = st[id]; return e && e.attributes && e.attributes[a] !== undefined ? e.attributes[a] : dflt; };
// 'HH:MM:SS' van een input_datetime → Date van vandaag
lib.todayAt = function (hhmm, now) {
  const [h, m] = String(hhmm || '00:00').split(':').map(Number);
  const d = new Date(now || Date.now()); d.setHours(h || 0, m || 0, 0, 0); return d;
};
// prijs-array normaliseren: [{start:Date, end:Date, prijs:Number}]
lib.prijsSlots = function (st, sensorId) {
  const e = st[sensorId]; if (!e) return [];
  const a = e.attributes || {};
  const raw = [...(a.today || []), ...(a.tomorrow || [])];
  const out = raw.map(h => ({ start: new Date(h.start), end: h.end ? new Date(h.end) : null, prijs: Number(h.all_in) }))
                 .filter(s => !isNaN(s.start) && Number.isFinite(s.prijs))
                 .sort((x, y) => x.start - y.start);
  for (let i = 0; i < out.length; i++) if (!out[i].end) out[i].end = i + 1 < out.length ? out[i + 1].start : new Date(out[i].start.getTime() + 3600e3);
  return out;
};
// Goedkoopste N uren (split toegestaan) binnen [van, tot) — port van cheapest_energy_hours(split=true)
lib.goedkoopsteUren = function (slots, n, van, tot, now) {
  const kand = slots.filter(s => s.start >= van && s.end <= tot);
  const gekozen = [...kand].sort((a, b) => a.prijs - b.prijs || a.start - b.start).slice(0, Math.max(0, n))
                           .sort((a, b) => a.start - b.start);
  // aaneengesloten slots samenvoegen tot blokken (zoals attribute 'blokken')
  const blokken = [];
  for (const s of gekozen) {
    const last = blokken[blokken.length - 1];
    if (last && last.end.getTime() === s.start.getTime()) { last.end = s.end; last.prices.push(s.prijs); }
    else blokken.push({ start: s.start, end: s.end, prices: [s.prijs] });
  }
  const nu = now || new Date();
  const is_now = gekozen.some(s => nu >= s.start && nu < s.end);
  return { is_now, blokken: blokken.map(b => ({ start: b.start.toISOString(), end: b.end.toISOString(),
           prices: b.prices, gem: b.prices.reduce((x, y) => x + y, 0) / b.prices.length })), n_gevonden: gekozen.length };
};
// Hysterese-latch: aan bij >grens (of <grens), pas uit bij grens∓marge. state = vorige uitkomst (bool)
lib.latch = function (waarde, grens, marge, richting, vorige) {
  // richting 'boven': waar als waarde > grens; blijft waar tot waarde <= grens - marge
  // richting 'onder': waar als waarde < grens; blijft waar tot waarde >= grens + marge
  if (richting === 'boven') return vorige ? waarde > grens - marge : waarde > grens;
  return vorige ? waarde < grens : waarde < grens - marge; // 'onder' = stap-2b-semantiek (start onder doel − marge, door tot doel)
};
global.set('ems_lib', lib);
return {};

const d = new Date();
const p = n => String(n).padStart(2, '0');
const lokaal = `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`;
msg.payload = {
  action: 'input_datetime.set_datetime',
  domain: 'input_datetime', service: 'set_datetime',
  target: { entity_id: ['input_datetime.ems_heartbeat'] },
  data: { datetime: lokaal }
};
return msg;

const lib = global.get('ems_lib'); const st = lib.states();
if (msg.topic === 'reset') { flow.set('pariteit', { n: 0, afw: 0, laatste: [] }); }
const p = global.get('ems_plan_regels'); if (!p) return null;
const ctx = flow.get('pariteit') || { n: 0, afw: 0, laatste: [] };
const checks = [
  ['netladen_gewenst', p.netladen_gewenst, lib.on(st, 'binary_sensor.ems_netladen_gewenst')],
  ['assist_toegestaan', p.assist_toegestaan, lib.on(st, 'binary_sensor.ems_batterij_assist_toegestaan')],
  ['goedkoopste_uren', p.goedkoopste_uren, lib.on(st, 'binary_sensor.ems_goedkoopste_uren')],
  ['herstel_nodig', p.herstel_nodig, lib.on(st, 'binary_sensor.ems_herstel_nodig')],
  ['ev_doelstroom', p.ev_stroom, lib.num(st, 'sensor.ems_ev_doelstroom', -1)],
];
const afw = checks.filter(([, nr, ha]) => nr !== ha).map(([k, nr, ha]) => `${k}: NR=${nr} HA=${ha}`);
ctx.n += 1;
if (afw.length) { ctx.afw += 1; ctx.laatste = [new Date().toLocaleString('nl-BE') + ' · ' + afw.join(' | '), ...ctx.laatste].slice(0, 20); }
flow.set('pariteit', ctx);
msg.payload = ctx.afw; msg.par = { n: ctx.n, laatste: ctx.laatste, ok_pct: ctx.n ? Math.round((1 - ctx.afw / ctx.n) * 1000) / 10 : null };
node.status({ fill: afw.length ? 'yellow' : 'green', shape: 'dot', text: `${ctx.afw}/${ctx.n} afwijkend` });
return msg;
